"""Input constructors only; no receive, PN-reconstruction or canonicalization model."""
def v(value,width=None):
    if width is None:width=next(w for w in [1,2,4,8] if value<2**(8*w-2))
    if width not in [1,2,4,8] or not 0<=value<2**(8*width-2):raise ValueError('varint')
    return (([1,2,4,8].index(width)<<(8*width-2))|value).to_bytes(width,'big')
def envelope(level,pn,body,cid=b'\xaa',scid=b'\xbb',token=b'',width=1,phase=0,spin=0,length_width=None):
    number=(pn%(2**(8*width))).to_bytes(width,'big')
    if level=='A':return bytes([0x40|(spin<<5)|(phase<<2)|(width-1)])+cid+number+body
    head=bytes([(0xc0 if level=='I' else 0xe0)|(width-1)])+b'\0\0\0\1'+bytes([len(cid)])+cid+bytes([len(scid)])+scid
    if level=='I':head+=v(len(token))+token
    return head+v(width+len(body),length_width)+number+body
def stream(sid,off,data,fin=False,offset=True,length=True):
    return bytes([8|(4 if offset else 0)|(2 if length else 0)|int(fin)])+v(sid)+(v(off) if offset else b'')+(v(len(data)) if length else b'')+data
def crypto(off,data):return b'\x06'+v(off)+v(len(data))+data
def datagram(wire,auth=(0,)):return {'datagram':{'wire':wire.hex(),'auth':list(auth)}}
def trace(events,connection=2**62-1,stream_credit=2**62-1,bidi=2**60,uni=2**60,cids=4,local_bidi=2,local_uni=2,local_cids=('aa','bb'),received=None):
    return {'limits':{'connection':connection,'stream':stream_credit,'bidi':bidi,'uni':uni,'cids':cids},'local':{'bidi':local_bidi,'uni':local_uni,'cids':list(local_cids)},'peer':{'cid':'cc','token':'00'*16},'received':received or {'I':None,'H':None,'A':None},'events':events}
